/* Rozwinięcie makiety na podstawie tras i schematów Pracuj.be. Wszystkie zapisy są demonstracyjne. */
const demoApplications=new Set([3]);
let profileData={name:'Michał Kowalski',occupation:'Operator wózka widłowego',city:'Antwerpia',experience:'3',skills:'Obsługa wózka, kompletowanie zamówień',languages:'Polski — ojczysty, angielski — podstawowy',certificates:'Uprawnienia na wózek widłowy',availability:'Od zaraz',radius:'25'};
let demoMessages=['Dzień dobry, dziękujemy za zainteresowanie ofertą. Czy odpowiada Panu rozmowa we wtorek o 10:00?'];
let profileNotice='',draftNotice='',proposalState='Nowa propozycja';
const field=(label,name,value='',type='text')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${['name','occupation','city','title'].includes(name)?'required':''}></label>`;
const area=(label,name,value='')=>`<label class="wide">${label}<textarea name="${name}" rows="3">${esc(value)}</textarea></label>`;
const demoNote='<p class="demo-note">Podgląd interaktywny · przykładowe dane. Zmiany działają do odświeżenia strony i nie są wysyłane do pracodawców.</p>';
const candidateLinks=[['candidate','Podsumowanie'],['profile','Mój profil'],['applications','Moje aplikacje'],['proposals','Propozycje pracy'],['messages','Wiadomości'],['saved','Zapisane oferty']];
const employerLinks=[['employer','Podsumowanie'],['newjob','Dodaj ofertę'],['talent','Kandydaci'],['company','Moja firma']];
sidebar=function(emp){return `<aside class="sidebar"><div class="side-person"><span class="company-icon">${emp?'NL':'MK'}</span><strong>${emp?'Northline Logistics':esc(profileData.name)}</strong><span>${emp?'Panel pracodawcy':'Profil kandydata'}</span></div><nav aria-label="Menu panelu">${(emp?employerLinks:candidateLinks).map(([v,t])=>button(t,v,'side-item '+(view===v?'active':''))).join('')}</nav></aside>`;};
const shell=(title,subtitle,body,emp=false)=>`${nav()}<main class="dashboard">${sidebar(emp)}<div class="dash-content extended"><span class="eyebrow">${emp?'TWOJA REKRUTACJA':'TWOJE MIEJSCE'}</span><h1>${title}</h1><p class="dash-intro">${subtitle}</p>${demoNote}${body}</div></main>${footer()}`;
const oldDetailExtended=detail;
detail=function(){if(theme!=='people')return oldDetailExtended();const j=jobs.find(x=>x.id===detailId)||jobs[0];return `${nav()}<main class="extended offer-page">${button('← Wszystkie oferty','jobs','text-link')}<div class="offer-layout"><div><span class="eyebrow">${j.category} / ${j.city}</span><h1>${j.title}</h1><p class="dash-intro">${j.company} · Belgia</p>${peopleCard(j)}<section class="paper"><h2>Na czym polega praca</h2><p>${j.desc}</p><h3>Twoje zadania</h3><ul><li>Realizacja zadań wspólnie z zespołem.</li><li>Dbanie o bezpieczeństwo i jakość wykonywanej pracy.</li><li>Przekazywanie informacji osobie prowadzącej zmianę.</li></ul><h3>Co warto umieć</h3><p>${j.requirements || 'Dokładność, współpraca i gotowość do nauki. Szczegółowe wymagania i uprawnienia pracodawca podaje przy stanowisku.'}</p><h3>Warunki i organizacja</h3><div class="info-pairs"><div><small>Warunki</small><strong>${j.tags.join(' · ')}</strong></div><div><small>Wynagrodzenie</small><strong>${j.salary?j.salary+' '+j.period:'Pracodawca nie podał stawki'}</strong></div><div><small>Język pracy</small><strong>Do ustalenia z pracodawcą</strong></div><div><small>Rozpoczęcie</small><strong>Termin do uzgodnienia</strong></div></div></section></div><aside><section class="paper apply-box"><span class="eyebrow">TWÓJ NASTĘPNY KROK</span><h2>Zgłoś się swoim profilem.</h2><p>Nie potrzebujesz osobnego pliku CV.</p>${button(demoApplications.has(j.id)?'Zobacz swoje zgłoszenie':'Aplikuj na tę ofertę',demoApplications.has(j.id)?'applications':'apply')}<button class="btn secondary" data-save="${j.id}" aria-pressed="${saved.has(j.id)}">${saved.has(j.id)?'Zapisano':'Zapisz ofertę'}</button><hr><h3>Przed aplikowaniem</h3><p>Sprawdź miejsce pracy, warunki dojazdu i zakres obowiązków.</p>${demoNote}</section></aside></div></main>${footer()}`;};
function profileScreen(){return shell('Twój paszport zawodowy.','Pokaż, co potrafisz. Bez układania CV.',`<div class="profile-banner"><span class="profile-avatar">MK</span><div><h2>${esc(profileData.name)}</h2><p>${esc(profileData.occupation)} · ${esc(profileData.city)}</p></div><span class="status good">${esc(profileData.availability)}</span></div><form id="profile-demo" class="paper demo-form"><p role="status">${profileNotice}</p><h2>Podstawowe informacje</h2><div class="form-grid">${field('Imię i nazwisko','name',profileData.name)}${field('Zawód','occupation',profileData.occupation)}${field('Miasto','city',profileData.city)}${field('Doświadczenie w latach','experience',profileData.experience,'number')}${area('Umiejętności','skills',profileData.skills)}${field('Języki i poziom','languages',profileData.languages)}${field('Uprawnienia i certyfikaty','certificates',profileData.certificates)}${field('Dostępność','availability',profileData.availability)}${field('Dojazd do pracy — km','radius',profileData.radius,'number')}</div><button class="btn" type="submit">Zapisz profil w podglądzie</button></form>`);}
function applicationsScreen(){return shell('Twoje zgłoszenia.','Sprawdź, na jakim etapie jest każda rozmowa.',`<div class="application-stack">${[...demoApplications].map(id=>{const j=jobs.find(x=>x.id===id);return `<article class="paper"><div class="section-head"><div><span class="eyebrow">${j.company}</span><h2>${j.title}</h2><p>${j.city}</p></div><span class="status">Wysłana · przykład</span></div><ol class="application-steps"><li class="done">Zgłoszenie wysłane</li><li>Pracodawca przegląda</li><li>Rozmowa</li><li>Decyzja</li></ol><button class="text-link" data-detail="${id}">Wróć do oferty →</button></article>`}).join('')}</div>`);}
function applyScreen(){const j=jobs.find(x=>x.id===detailId)||jobs[0];return shell('Zrób pierwszy krok.',j.title+' · '+j.company,`<form id="application-demo" class="paper demo-form"><h2>Twój profil jest gotowy do dołączenia.</h2><p>${esc(profileData.name)} · ${esc(profileData.occupation)}</p>${button('Sprawdź profil','profile','text-link')}<div class="form-grid">${field('Telefon — opcjonalnie','phone','','tel')}<label>Dostępność<select name="availability"><option>Od zaraz</option><option>W ciągu miesiąca</option><option>Do uzgodnienia</option></select></label>${area('Wiadomość do pracodawcy — opcjonalnie','message')}</div><label class="check-row"><input type="checkbox" required>Potwierdzam demonstracyjne zgłoszenie. Żadne dane nie zostaną wysłane.</label><button class="btn">Wypróbuj wysłanie zgłoszenia</button></form>`);}
function messagesScreen(){return shell('Porozmawiaj o konkretach.','Northline Logistics · Operator wózka widłowego',`<section class="paper conversation"><header><span class="company-icon">NL</span><div><strong>Zespół rekrutacji</strong><p>Rozmowa demonstracyjna</p></div></header><div class="chat-log">${demoMessages.map((m,i)=>`<p class="bubble ${i?'mine':''}">${esc(m)}</p>`).join('')}</div><form id="message-demo" class="demo-form"><label>Twoja wiadomość<textarea name="message" required maxlength="2000" rows="3" placeholder="Napisz odpowiedź…"></textarea></label><button class="btn">Dodaj odpowiedź w podglądzie</button></form></section>`);}
function proposalsScreen(){return shell('Pracodawcy też szukają Ciebie.','Tutaj trafiają propozycje dotyczące Twojego doświadczenia.',`<section class="paper"><div class="section-head"><div><span class="eyebrow">NORTHLINE LOGISTICS</span><h2>Porozmawiajmy o pracy w Antwerpii.</h2></div><span class="status">${proposalState}</span></div><p>Zainteresowało nas Twoje doświadczenie w obsłudze wózków. Chętnie opowiemy o stanowisku i warunkach pracy.</p>${peopleCard(jobs[0])}<div class="action-row"><button class="btn" data-proposal="Zainteresowanie potwierdzone">Jestem zainteresowany</button><button class="btn secondary" data-proposal="Propozycja odrzucona">Nie tym razem</button>${button('Przejdź do wiadomości','messages','text-link')}</div><p>Odpowiedź w tym podglądzie nie jest wysyłana do firmy.</p></section>`);}
function savedScreen(){return shell('Wróć do dobrych ofert.','Twoje zapisane miejsca pracy.',saved.size?`<div class="p-job-grid">${jobs.filter(j=>saved.has(j.id)).map(peopleCard).join('')}</div>`:`<section class="paper empty"><h2>Jeszcze nic tu nie ma.</h2><p>Zapisz ofertę przyciskiem zakładki, a pojawi się w tym miejscu.</p>${button('Przeglądaj oferty','jobs')}</section>`);}
function newJobScreen(){return shell('Opisz pracę. Poznaj ludzi.','Formularz oferty — skrócony podgląd sekcji z repozytorium.',`<form id="job-demo" class="paper demo-form"><p role="status">${draftNotice}</p><h2>01 / Stanowisko i miejsce</h2><div class="form-grid">${field('Nazwa stanowiska','title','Pracownik magazynu')}${field('Miasto','city','Antwerpia')}<label>Branża<select name="category"><option>Logistyka</option><option>Produkcja</option><option>Budownictwo</option><option>Technika</option></select></label><label>Rodzaj umowy<select name="contract"><option>Umowa o pracę</option><option>Praca tymczasowa</option><option>B2B</option></select></label></div><h2>02 / Wynagrodzenie</h2><p>Stawka jest opcjonalna. Bez niej karta pokazuje miejsce i warunki.</p><div class="form-grid">${field('Od — EUR brutto za godzinę','salaryMin','','number')}${field('Do — EUR brutto za godzinę','salaryMax','','number')}</div><h2>03 / Obowiązki i wymagania</h2><div class="form-grid">${area('Opis stanowiska','description','Kompletowanie zamówień i przygotowywanie przesyłek.')}${area('Wymagane umiejętności, języki i uprawnienia','requirements')}</div><h2>04 / Organizacja pracy</h2><div class="form-grid"><label class="check-row"><input type="checkbox" name="accommodation">Zakwaterowanie</label><label class="check-row"><input type="checkbox" name="transport">Transport do pracy</label></div><button class="btn">Zapisz i pokaż przykładową ofertę</button><p>To skrócona makieta. Docelowy kreator w repozytorium ma 9 kroków.</p></form>` ,true);}
function talentScreen(){return shell('Umiejętności na pierwszym planie.','Przegląd przykładowych profili kandydatów.',`<div class="talent-grid">${[['MK','Michał Kowalski','Operator wózka widłowego','3 lata doświadczenia','Antwerpia'],['AN','Anna Nowak','Pracownik magazynu','2 lata doświadczenia','Gandawa']].map(([a,n,o,e,c])=>`<article class="paper"><span class="profile-avatar">${a}</span><h2>${n}</h2><p>${o}</p><div class="info-pairs"><div><small>Doświadczenie</small><strong>${e}</strong></div><div><small>Miasto</small><strong>${c}</strong></div></div><details><summary>Zobacz umiejętności</summary><p>Kompletowanie zamówień, praca zespołowa, kontrola jakości.</p><p>Przykładowy profil do oceny wyglądu karty.</p></details></article>`).join('')}</div>`,true);}
function companyScreen(){return shell('Twoja firma, po ludzku.','Informacje, które pomagają kandydatom poznać miejsce pracy.',`<section class="paper company-preview"><img src="assets/warehouse.jpg" alt="Ilustracyjne zdjęcie magazynu"><span class="eyebrow">LOGISTYKA / ANTWERPIA</span><h2>Northline Logistics</h2><p>Przykładowy zespół magazynowy. Tutaj firma opisze organizację pracy, wdrożenie nowych osób oraz codzienne zadania.</p><div class="info-pairs"><div><small>Weryfikacja firmy</small><strong>Oczekuje na weryfikację</strong></div><div><small>Kontakt w sprawie rekrutacji</small><strong>Przez wiadomości w serwisie</strong></div></div>${button('Dodaj ofertę','newjob')}</section>`,true);}
const extraScreens={profile:profileScreen,applications:applicationsScreen,apply:applyScreen,messages:messagesScreen,proposals:proposalsScreen,saved:savedScreen,newjob:newJobScreen,talent:talentScreen,company:companyScreen};
const oldExtendedRender=render;
render=function(){oldExtendedRender();if(theme==='people'&&extraScreens[view])document.getElementById('screen').innerHTML=extraScreens[view]();};
const oldExtendedCandidate=candidate;candidate=function(){return oldExtendedCandidate().replace('<span class="tag">Podgląd przykładowego profilu</span>',button('Uzupełnij swój profil','profile'));};
const oldExtendedEmployer=employer;employer=function(){return oldExtendedEmployer().replace('<span class="tag">Przykładowy panel</span>',button('Dodaj ofertę','newjob'));};
document.addEventListener('submit',e=>{const f=e.target;if(!['profile-demo','application-demo','message-demo','job-demo'].includes(f.id))return;e.preventDefault();const d=Object.fromEntries(new FormData(f));if(f.id==='profile-demo'){profileData={...profileData,...d};profileNotice='Profil zapisany w tym podglądzie.';}if(f.id==='application-demo'){demoApplications.add(detailId);view='applications';}if(f.id==='message-demo'){demoMessages.push(d.message);view='messages';}if(f.id==='job-demo'){if(d.salaryMin&&d.salaryMax&&+d.salaryMin>+d.salaryMax){draftNotice='Górna stawka musi być większa lub równa dolnej. Wpisane dane pozostają w formularzu.';f.querySelector('[role=status]').textContent=draftNotice;return;}const id=Math.max(...jobs.map(j=>j.id))+1;jobs.push({id,title:esc(d.title),company:'Northline Logistics',city:esc(d.city),category:esc(d.category),salary:d.salaryMin?(d.salaryMax?d.salaryMin+'–'+d.salaryMax:'od '+d.salaryMin)+' €':'',period:d.salaryMin?'brutto / godz.':'',tags:[d.contract,...(d.accommodation?['Zakwaterowanie']:[]),...(d.transport?['Transport']:[])],initials:'NL',desc:esc(d.description),requirements:esc(d.requirements)});detailId=id;view='detail';}render();});
document.addEventListener('click',e=>{const b=e.target.closest('[data-proposal]');if(b){proposalState=b.dataset.proposal;render();}});
const extraTab=document.createElement('button');extraTab.dataset.view='profile';extraTab.textContent='Profil zawodowy';extraTab.setAttribute('aria-pressed','false');document.getElementById('views').append(extraTab);
const extraEmployerTab=document.createElement('button');extraEmployerTab.dataset.view='newjob';extraEmployerTab.textContent='Dodaj ofertę';extraEmployerTab.setAttribute('aria-pressed','false');document.getElementById('views').append(extraEmployerTab);
const requestedExtra=requestedConceptHash.slice(1).split('/');if(requestedExtra[0]==='people'&&extraScreens[requestedExtra[1]])view=requestedExtra[1];
render();
